const key='suda-piano-language';
const words={
 '唐秋鸣课题设计实例':'Tang Qiuming · Research Prototype','苏州大学钢琴演奏':'Suzhou University Piano Studio','琴谱与演奏':'Scores & Performance','乐谱库':'Score Library','上传钢琴谱':'Upload piano score','上传简谱':'Upload numbered notation','演奏控制':'Performance','播放':'Play','重播':'Replay','开始练习':'Start practice','暂停练习':'Pause practice','从头练习':'Restart practice','服务与导入':'Import & Services','设置':'Settings','导入 MusicXML 或 MIDI':'Import MusicXML or MIDI','导入绑定演唱音频':'Bind vocal audio','演奏工作区':'Performance Workspace','电子谱':'Engraved score','简谱':'Numbered notation','原稿 PDF':'Original PDF','试听':'Preview','打开示例谱':'Open sample score','未选择文件':'No file selected'
};
function translate(node,en){const zh=node.dataset.zh??node.textContent.trim();if(!zh)return;node.dataset.zh=zh;node.textContent=en&&words[zh]?words[zh]:zh;}
function apply(locale){const en=locale==='en';document.documentElement.lang=en?'en':'zh-CN';document.documentElement.classList.toggle('language-en',en);for(const selector of ['.brand strong','.top-title','.setup-head h1','.section-title strong','.upload strong','.playback-panel>.section-label','.playback-buttons button','.practice-actions button','.technical summary','.xml-label','.heading h2','.heading button','.view-buttons button','.import-actions button','#file-info','[data-panel]'])document.querySelectorAll(selector).forEach(node=>translate(node,en));const button=document.querySelector('#language-switch');if(button){button.textContent=en?'中文':'EN';button.setAttribute('aria-label',en?'切换为中文':'Switch language');}document.dispatchEvent(new CustomEvent('languagechange',{detail:{locale}}));}
addEventListener('DOMContentLoaded',()=>{apply(localStorage.getItem(key)==='en'?'en':'zh');document.querySelector('#language-switch')?.addEventListener('click',()=>{const next=document.documentElement.lang==='en'?'zh':'en';localStorage.setItem(key,next);apply(next);});});
